-- Ríos y arroyos de la primera sección del Delta, bajados de OpenStreetMap (ODbL) el 7 de noviembre de 2026.
-- Volver a correr es seguro: hace upsert por osm_id y después regenera el grafo.
on conflict (osm_id) do update set name = excluded.name, kind = excluded.kind, geom = excluded.geom;
select rebuild_water_graph();
